let h=load("header");
h=h.replace("def YF",`def YBase {m : ℕ} (z : YEucl (m + 1)) : YEucl m :=
  WithLp.toLp 2 (fun i => z i.castSucc)
def YLast {m : ℕ} (z : YEucl (m + 1)) : ℝ := z (Fin.last m)
def YF`);
store("header",h);
const steps=[];
function add(id,statement,inputs,source_steps,explanation){steps.push({id,statement,inputs,source_steps,explanation})}
add("T001","∀ (m : ℕ) (A : Set (YEucl m)) (s : ℝ), 0 < s → YHaus s A = MeasureTheory.Measure.hausdorffMeasure s A",[],["S001"],"Unfold the checked hausdorffMeasure_apply formula. Positive real scales cover all finite positive extended scales; the infinity scale contributes no larger infimum. Positive real powers give zero for empty members, so natural-number covers with empty padding implement the source countable covers exactly.");
add("T002","∀ (m : ℕ) (A : Set (YEucl m)), YCritical A",["T001"],["S002"],"Export all clauses of N001. Use the pinned four critical-exponent lemmas directly, passing the nonnegative exponent Real.toNNReal s and proving its real/ENNReal coercions equal s/ofReal s from 0<s. dimH has ENNReal codomain and Borel measurable structure. No M premise ports.");
add("T003","(∀ (m : ℕ) (x y : YEucl m) (t u : ℝ), dist (YJoin x t) (YJoin y u) = Real.sqrt (dist x y ^ 2 + |t-u| ^ 2)) ∧ (∀ (m : ℕ) (z : YEucl (m+1)), YJoin (YBase z) (YLast z) = z) ∧ (∀ (m : ℕ) (x : YEucl m) (t : ℝ), YBase (YJoin x t) = x ∧ YLast (YJoin x t) = t) ∧ (∀ m : ℕ, LipschitzWith 1 (@YBase m) ∧ LipschitzWith 1 (@YLast m)) ∧ Isometry YLine ∧ Function.Surjective YLine",[],["S009","S010","S012","S015","S023"],"Shared implementation of the actual coordinate identifications in D001. EuclideanSpace.dist_eq/dist_sq_eq compute the sum of squared coordinate distances; Fin.snoc appends the last coordinate. Split the finite sum into castSucc coordinates and last. Derive projection contractions and the one-coordinate line isometry, including m=0. These are obligations, not properties hidden in the definitions.");
add("T004","(∀ (s δ : ℝ), 0 < s → 0 < δ → YContent s δ YI = YContent s δ (YLine '' YI)) ∧ (∀ s : ℝ, 0 < s → YHaus s YI = YHaus s (YLine '' YI)) ∧ dimH YI = dimH (YLine '' YI)",["T003"],["S009"],"Check the real-line/one-coordinate-vector conversion actually used by S009. Push covers forward and pull them back through the surjective isometry YLine; diameters and costs agree, giving content and measure equality. The same isometry preserves native Hausdorff dimension (direct library isometry transport or its defining critical exponents). This is the only real-line/vector conversion; there is no change of norm.");
add("T005","(∃ L : ℝ, 0 < L ∧ ∀ x ∈ E, ∀ i : Fin n, |x i| ≤ L) ∧ (∀ (s δ : ℝ), 0 < s → 0 < δ → YContent s δ E < ⊤)",["H002"],["S003"],"Use compactness for a bounding coordinate box and finite ball covers at each positive scale; enumerate finite covers with empty padding. Contents and finite costs stay in ENNReal, so no toReal of infinity is introduced.");
add("T006","(0 ≤ dimH E ∧ dimH E ≤ (n : ℝ≥0∞) ∧ dimH E < ⊤) ∧ (n = 0 → E = Set.univ ∧ E.Subsingleton ∧ dimH E = 0) ∧ (∀ (s δ : ℝ), 0 < s → 0 < δ → YContent s δ E < ⊤)",["H001","T002","T005"],["S004","S005"],"Export N002 in full. For n≥1 subdivide the bounding box into O(h^(-n)) cubes of diameter at most sqrt n*h, so each exponent a>n has zero Hausdorff measure. Apply T002 and let a decrease to n. For n=0 use nonemptiness and the unique empty tuple; singleton covers have zero positive cost. Retain finite contents from T005.");
add("T007","∀ a : ℝ, 1 < a → YHaus a YI = 0",[],["S006"],"Use k equal closed intervals with total a-cost k^(1-a); at each positive scale admissibility holds eventually and costs tend to zero.");
add("T008","∀ (δ : ℝ), 0 < δ → ∀ U : ℕ → Set ℝ, YCover δ YI U → (1 : ℝ≥0∞) ≤ ∑' i, Metric.ediam (U i)",[],["S007"],"Keep only nonempty members (a subtype of naturals), enlarge bounded real sets to open intervals with geometric total error ε. Apply Lebesgue length subadditivity and volume I=1, then remove ε with the original cover fixed. Empty padded terms contribute zero.");
add("T009","(∀ (s δ : ℝ), 0 < s → s < 1 → 0 < δ → ∀ U : ℕ → Set ℝ, YCover δ YI U → (ENNReal.ofReal δ) ^ (s-1) ≤ YCost s U) ∧ (∀ s : ℝ, 0 < s → s < 1 → YHaus s YI = ⊤)",["T008"],["S008"],"For positive diameters ≤δ use the negative exponent s-1; treat diameter zero separately. Sum and use T008, then infimize over covers. As δ tends to zero the lower bound diverges. Real powers are on ENNReal after ofReal; δ>0 is essential.");
add("T010","dimH YI = 1 ∧ (∀ a : ℝ, 1 < a → YHaus a YI = 0) ∧ (∀ (s δ : ℝ), 0 < s → s < 1 → 0 < δ → ∀ U : ℕ → Set ℝ, YCover δ YI U → (1 : ℝ≥0∞) ≤ ∑' i, Metric.ediam (U i) ∧ (ENNReal.ofReal δ) ^ (s-1) ≤ YCost s U) ∧ (∀ s : ℝ, 0 < s → s < 1 → YHaus s YI = ⊤)",["T002","T004","T007","T008","T009"],["S009"],"Export every N003 clause. Use T004 to transfer the interval to Eucl(1), apply T002, and transfer dimension back. Upper exponents a>1 and lower 0<s<1 force dimension exactly one by order completeness; retain the coverwise estimates.");
add("T011","n = 0 → dimH (YF E) ≤ dimH E + 1",["T002","T003","T006","T010"],["S010"],"Under n=0, N002 identifies E with the singleton and D=0. Send covers of I through t↦YJoin (empty tuple) t, after intersecting members with I. T003 gives the isometry; obtain zero a-measure for a>1, apply T002 and let a decrease to one.");
add("T012","1 ≤ n → ∀ q : ℝ, 0 < q → dimH E < ENNReal.ofReal q → ∀ r : ℝ, 0 < r → r ≤ 1 → ∀ ε : ℝ, 0 < ε → ∃ U : ℕ → Set (YEucl n), YCover r E U ∧ (∀ i, (U i).Nonempty → 0 < Metric.ediam (U i)) ∧ YCost q U < ENNReal.ofReal ε",["T002"],["S011"],"From zero q-measure obtain an r-cover of cost below ε/2. Retain original indices, discard empty members, and replace nonempty zero-diameter singletons by arbitrarily small positive-radius balls. Because n≥1 these balls have positive diameter; assign geometric q-cost bounds. Empty padding remains legal.");
add("T013","1 ≤ n → ∀ q : ℝ, 0 < q → dimH E < ENNReal.ofReal q → ∀ r : ℝ, 0 < r → r ≤ 1 → ∀ ε : ℝ, 0 < ε → ∃ V : ℕ → Set (YEucl (n+1)), YCover (Real.sqrt 2 * r) (YF E) V ∧ YCost (q+1) V < ENNReal.ofReal (2 * (Real.sqrt 2) ^ (q+1) * ε)",["T003","T012"],["S012"],"Take T012's cover, partition I into ceil(1/r_i) intervals for each nonempty member, and enumerate the countable union of finite product families. The coordinate distance identity bounds product diameter by sqrt 2*r_i. Use ceil(1/r_i)≤2/r_i and the source cost estimate; padding empty terms costs zero.");
add("T014","1 ≤ n → ∀ q : ℝ, dimH E < ENNReal.ofReal q → YHaus (q+1) (YF E) = 0 ∧ dimH (YF E) ≤ ENNReal.ofReal (q+1)",["T002","T006","T013"],["S013"],"N002 and q>D imply q>0. For each target δ>0 choose r=min(1,δ/sqrt 2) and arbitrary ε>0 in T013. The fixed finite cost multiplier lets content vanish, hence Hausdorff measure vanishes. Apply T002 in ambient dimension n+1.");
add("T015","dimH (YF E) ≤ dimH E + 1",["T006","T011","T014"],["S014"],"Export N004. The finite ENNReal dimension D from N002 has a real value only after proving finiteness. Use q>D tending to D to get the bound in the n≥1 branch; combine with T011 in the exhaustive natural-number cases.");
const majorant="∑' i, (Metric.ediam (V i)) ^ s * (J i).indicator (fun _ : ℝ => (1 : ℝ≥0∞)) t";
add("T016",`∀ (s δ : ℝ), 0 < s → 0 < δ → ∀ V : ℕ → Set (YEucl (n+1)), YCover δ (YF E) V → ∀ ε : ℝ, 0 < ε → ∃ J : ℕ → Set ℝ, (∀ i, IsOpen (J i)) ∧ (∀ i, YLast '' (V i) ⊆ J i) ∧ (∀ i, MeasureTheory.volume (J i) ≤ Metric.ediam (V i) + ENNReal.ofReal (ε * (2 : ℝ) ^ (-(i : ℤ)-1) / (1 + (Metric.ediam (V i)).toReal ^ s))) ∧ (∀ t ∈ YI, YContent s δ E ≤ ${majorant})`,["T003"],["S015","S016","S017"],"Use the checked coordinate projections. For each nonempty V_i take the open enlargement of its last projection with η_i=ε*2^(-i-1)/(1+rho_i^s), where rho_i=(ediam V_i).toReal is justified by δ-finiteness. For empty V_i use J_i=∅. The projected first coordinates with t∈J_i cover E; their diameter bound gives the pointwise majorant. No measurability of V_i or its projections is required; only J_i is open.");
add("T017","∀ (s δ : ℝ), 0 < s → 0 < δ → ∀ V : ℕ → Set (YEucl (n+1)), YCover δ (YF E) V → YContent s δ E ≤ YCost (s+1) V",["T006","T016"],["S018"],"Integrate the pointwise majorant for each ε>0 over volume.restrict YI. Openness supplies measurability and hence a.e. measurability of each ENNReal-valued indicator times the finite nonnegative coefficient. Apply the checked MeasureTheory.lintegral_tsum with index ℕ. Volume(YI)=1 and the interval length bounds give c≤cost+ε by the geometric error sum. If cost=∞ finish immediately; otherwise remove ε, keeping V fixed. N002 supplies finite c.");
add("T018","∀ (s δ : ℝ), 0 < s → 0 < δ → YContent s δ E ≤ YContent (s+1) δ (YF E)",["T017"],["S019"],"Export N005: infimize the coverwise inequality over every countable δ-cover V. Same scale, Euclidean metric, all n including zero, and arbitrary covering sets.");
add("T019","0 < dimH E → dimH E + 1 ≤ dimH (YF E)",["T002","T006","T018"],["S020","S021"],"Export N006. For each real 0<s<D, T002 gives infinite s-measure of E; take the supremum in T018 to get infinite (s+1)-measure of F, hence dimension≥s+1. Finiteness and positivity of D justify taking s↑D. The final inequality is in ENNReal, allowing infinite dimension of F.");
add("T020","dimH E = 0 → (1 : ℝ≥0∞) ≤ dimH (YF E) ∧ (1 : ℝ≥0∞) = dimH E + 1",["H001","T002","T003","T010"],["S022","S023","S024"],"Export N007. Select x0∈E using H001. T003 proves t↦YJoin x0 t is isometric. Pull arbitrary covers of F back to I to compare contents and their suprema. N003 gives infinite s-measure for 0<s<1, so T002 gives dimH F≥s. Let s↑1 and substitute D=0; the proof includes n=0.");
add("T021","dimH (YF E) = dimH E + 1",["T006","T015","T019","T020"],["S025"],"Export the full target P. N002 gives the exhaustive D>0 or D=0 cases; use their lower bounds and N004's upper bound, then antisymmetry. YF is exactly the coordinate-concatenated E×[0,1].");
const artifact={header:h,parameters:load("params"),premise_types:{H001:"E.Nonempty",H002:"IsCompact E"},conclusion_type:"dimH (YF E) = dimH E + 1",representation:"n : ℕ and E : Set (EuclideanSpace ℝ (Fin n)) preserve every ambient dimension including zero. The actual pinned EuclideanSpace is PiLp 2 (fun _ => ℝ): 2 is the extended-nonnegative Lp exponent, and Fin n is the finite coordinate index, not an order/capability assumption. Its distance is the square root of the sum of squared coordinate distances. WithLp.toLp changes the type synonym and Fin.snoc appends one coordinate; YF uses this concatenation inside Eucl(n+1), never the default sup metric on a product. T003 proves its distance formula, inverses and projection contractions. YLine and T004 check the real-line/Eucl(1) identification already used in the source. Metric.ediam is the ENNReal supremum of pairwise edist, with empty diameter zero. YCover uses arbitrary sequences of subsets, no measurability restriction; finite or other countable covers are represented with empty padding. YCost uses ENNReal real powers; every use has positive exponent, so empty terms vanish. YContent infimizes those costs at positive real scales; YHaus supremizes positive real scales. The equality with native unnormalized hausdorffMeasure is an obligation T001, not a definition. YCritical packages exactly the critical-exponent clauses. dimH is the native ENNReal supremum over nonnegative real exponents with infinite Borel Hausdorff measure, matching D005/D006 including infinity and empty supremum zero. ENNReal.ofReal s identifies a positive real exponent with its extended value; n casts to a finite ENNReal natural. D remains dimH E until T006 proves finiteness; any later toReal requires this fact. Lebesgue integration uses the native real volume and restricted measure; Borel-measurable open intervals give the requisite a.e. measurable nonnegative summands, agreeing with Lebesgue length/integration for these functions. The pinned M001-M006 are used directly as library theorems, not project premises. Background notes remain optional implementation references.",objects:[],steps,terminal:"T021",source_outputs:{N001:"T002",N002:"T006",N003:"T010",N004:"T015",N005:"T018",N006:"T019",N007:"T020",P:"T021"},endpoint_correspondence:{P:{mode:"direct",explanation:"For every n:ℕ and every subset E of the Euclidean n-space, the only project assumptions are E.Nonempty and IsCompact E. Fin n indexes all n coordinates, including the empty index at n=0. YI is exactly the closed real unit interval. YF E consists exactly of coordinate concatenations of x∈E and t∈[0,1] in Euclidean (n+1)-space; T003 proves the source sqrt(dist(x,y)^2+|t-u|^2) distance formula. Thus no metric-change hypothesis or product norm conversion is assumed. Native dimH is the representation fixed by D005/D006; T001/T002 prove its required unnormalized-covering bridge. Both sides of the equality use ENNReal Hausdorff dimension and addition of one, so infinity is preserved. The parameter domains, quantification, nonemptiness, compactness and entire conclusion are precisely the frozen target, with n=0 included."}}};
store("interface",artifact);
